package com.salespunch360.mobile.ui.account.sales
import androidx.compose.foundation.layout.*;import androidx.compose.foundation.lazy.LazyColumn;import androidx.compose.foundation.lazy.itemsIndexed;import androidx.compose.material3.*;import androidx.compose.runtime.*;import androidx.compose.ui.Modifier;import androidx.compose.ui.unit.dp;import com.salespunch360.mobile.account.*
@Composable fun SalesDocumentEditor(draft:SalesEditorDraft,options:SalesOptions,saving:Boolean,onDraft:(SalesEditorDraft)->Unit,onAdd:()->Unit,onLine:(Int,SalesLineDraft)->Unit,onRemove:(Int)->Unit,onClose:()->Unit,onSave:()->Unit){val sources=options.sourceDocuments.filter{it.str("type")=="SALES_INVOICE"&&it.str("branchId")==draft.branchId&&it.str("customerId")==draft.customerId};val sourceLines=sources.firstOrNull{it.str("id")==draft.sourceDocumentId}?.array("lines").orEmpty();AlertDialog(onDismissRequest={if(!saving)onClose()},title={Text("New ${draft.type.replace('_',' ')}")},confirmButton={Button(enabled=!saving&&draft.branchId.isNotBlank()&&draft.customerId.isNotBlank()&&draft.lines.all{it.quantity.toDoubleOrNull()?.let{x->x>0}==true&&(it.sourceId.isNotBlank()||it.itemName.isNotBlank())},onClick=onSave){Text(if(saving)"Saving…" else "Create draft")}},dismissButton={TextButton(enabled=!saving,onClick=onClose){Text("Cancel")}},text={LazyColumn(verticalArrangement=Arrangement.spacedBy(10.dp)){item{SelectField("Document type",draft.type,options.types.map{it to it.replace('_',' ')}){onDraft(draft.copy(type=it))}};item{SelectField("Branch",draft.branchId,options.branches.map{it.id to it.name}){onDraft(draft.copy(branchId=it,customerId=""))}};item{SelectField("Customer",draft.customerId,options.customers.filter{it.branchId==draft.branchId}.map{it.id to it.name}){onDraft(draft.copy(customerId=it))}};if(draft.type=="CREDIT_NOTE")item{SelectField("Original invoice",draft.sourceDocumentId,sources.map{it.str("id") to it.str("documentNumber")}){onDraft(draft.copy(sourceDocumentId=it))}};item{OutlinedTextField(draft.issueDate,{onDraft(draft.copy(issueDate=it))},label={Text("Issue date (YYYY-MM-DD)")})};item{OutlinedTextField(draft.dueDate,{onDraft(draft.copy(dueDate=it))},label={Text("Due date (optional)")})};item{SelectField("Tax mode",draft.taxMode,listOf("EXCLUSIVE" to "Exclusive","INCLUSIVE" to "Inclusive")){onDraft(draft.copy(taxMode=it))}};item{OutlinedTextField(draft.stateOfSupplyCode,{onDraft(draft.copy(stateOfSupplyCode=it))},label={Text("State of supply code")})};itemsIndexed(draft.lines){index,line->SalesLineEditor(index,line,draft,options,sourceLines,onLine,onRemove)};item{OutlinedButton(onAdd,Modifier.fillMaxWidth()){Text("Add line")}};item{OutlinedTextField(draft.notes,{onDraft(draft.copy(notes=it))},label={Text("Notes")},minLines=2)};item{Text("Displayed line values are previews. Tax, totals, numbering, stock, and posting are confirmed by the server.",style=MaterialTheme.typography.bodySmall)}}})}
@Composable private fun SalesLineEditor(index:Int,line:SalesLineDraft,draft:SalesEditorDraft,options:SalesOptions,sourceLines:List<kotlinx.serialization.json.JsonObject>,onLine:(Int,SalesLineDraft)->Unit,onRemove:(Int)->Unit){val masters=when(line.lineType){"PRODUCT"->options.products;"SERVICE"->options.services;"WORK_PACKAGE"->options.workPackages;else->emptyList()};ElevatedCard{Column(Modifier.padding(12.dp),verticalArrangement=Arrangement.spacedBy(6.dp)){Text("Line ${index+1}");if(draft.type=="CREDIT_NOTE")SelectField("Original line",line.sourceCommercialLineId,sourceLines.map{it.str("id") to "${it.str("itemName")} · ${it.str("quantity")}"}){id->val source=sourceLines.first{it.str("id")==id};onLine(index,line.copy(sourceCommercialLineId=id,lineType=source.str("lineType"),sourceId=source.str("productId").ifBlank{source.str("serviceId").ifBlank{source.str("workPackageId")}},itemName=source.str("itemName"),quantity=source.str("quantity"),rate=source.str("rate"),taxRate=source.str("taxRate"))};SelectField("Type",line.lineType,listOf("PRODUCT" to "Product","SERVICE" to "Service","WORK_PACKAGE" to "Work package","CUSTOM" to "Custom")){onLine(index,line.copy(lineType=it,sourceId=""))};if(line.lineType=="CUSTOM")OutlinedTextField(line.itemName,{onLine(index,line.copy(itemName=it))},label={Text("Item name")}) else SelectField("Item",line.sourceId,masters.map{it.id to it.name}){id->val m=masters.first{it.id==id};onLine(index,line.copy(sourceId=id,rate=m.rate.orEmpty(),taxRate=m.taxRate.orEmpty()))};Row(horizontalArrangement=Arrangement.spacedBy(6.dp)){OutlinedTextField(line.quantity,{onLine(index,line.copy(quantity=it))},label={Text("Qty")},modifier=Modifier.weight(1f));OutlinedTextField(line.rate,{onLine(index,line.copy(rate=it))},label={Text("Rate")},modifier=Modifier.weight(1f))};Row(horizontalArrangement=Arrangement.spacedBy(6.dp)){SelectField("Discount",line.discountType,listOf("" to "None","PERCENTAGE" to "%","FIXED" to "Fixed"),Modifier.weight(1f)){onLine(index,line.copy(discountType=it))};OutlinedTextField(line.discountValue,{onLine(index,line.copy(discountValue=it))},label={Text("Discount")},modifier=Modifier.weight(1f))};OutlinedTextField(line.taxRate,{onLine(index,line.copy(taxRate=it))},label={Text("GST %")});if(line.sourceId.isNotBlank()&&masters.firstOrNull{it.id==line.sourceId}?.trackInventory==true)SelectField("Warehouse",line.warehouseId,options.warehouses.filter{it.branchId==draft.branchId}.map{it.id to it.name}){onLine(index,line.copy(warehouseId=it))};if(draft.lines.size>1)TextButton({onRemove(index)}){Text("Remove line")}}}}
@OptIn(ExperimentalMaterial3Api::class)@Composable fun SelectField(label:String,value:String,values:List<Pair<String,String>>,modifier:Modifier=Modifier,onChange:(String)->Unit){var open by remember{mutableStateOf(false)};ExposedDropdownMenuBox(open,{open=!open},modifier){OutlinedTextField(values.firstOrNull{it.first==value}?.second.orEmpty(),{},readOnly=true,label={Text(label)},modifier=Modifier.menuAnchor(MenuAnchorType.PrimaryNotEditable).fillMaxWidth());ExposedDropdownMenu(open,{open=false}){values.forEach{(id,text)->DropdownMenuItem({Text(text)},{onChange(id);open=false})}}}}
